package cli

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"net/netip"
	coreapi "opnsense-cli/opnsense/api"
	"opnsense-cli/opnsense/api/firewall"
	"path/filepath"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"unicode"
)

// The four /firewall/nat menus (source, destination, one-to-one, npt) share one implementation: a
// firewallNatKind describes the fields of a rule type, firewallNatRegister adds the commands. Rules are selected
// by the # of print, the uuid or the description; the description is the natural key of add. Rules generated by
// OPNsense (anti-lockout, automatic outbound NAT) are listed, but can not be changed

const firewallNatItemHelp = "the #, uuid or description of the rule"

// firewallNatConv tells how an argument value is converted to the API value and back
type firewallNatConv int

const (
	firewallNatText     firewallNatConv = iota // as given (trimmed)
	firewallNatFlag                            // Bool argument, "1" / "0"
	firewallNatList                            // List argument, comma joined
	firewallNatMapped                          // one of values, mapped to the API value
	firewallNatProtocol                        // a protocol name, normalized by firewallNatKind.protocol
)

// firewallNatField maps a field argument to an API field
type firewallNatField struct {
	arg  Arg
	api  string // flat API field, e.g. "destination.port"
	conv firewallNatConv
	// values maps the argument values to API values for firewallNatMapped: {argument value, API value}
	values [][2]string
	// def is the API value of the model default, add ... replace sends it for fields that are not given
	def string
	// keep fields are not reset by add ... replace (sequence)
	keep bool
	// required for add
	required bool
}

// firewallNatKind describes one NAT rule type
type firewallNatKind struct {
	path  string // menu path, e.g. "firewall/nat/source"
	help  string
	long  string // added to the help of add and set
	rules func(api *firewall.FirewallApi) *firewall.NatRules
	// fields are the field arguments, without description and disabled (they are common)
	fields []firewallNatField
	// protocol normalizes a protocol name for the API (source NAT wants TCP, d_nat tcp)
	protocol func(string) string
	// columns and row are the kind specific print columns, between DISABLED/AUTO and DESCRIPTION
	columns []string
	row     func(fields firewall.NatRuleFields) []string
	// check validates the complete fields of a rule (the current fields with the changes), e.g. ports only for
	// tcp/udp. The fields are API fields
	check func(fields firewall.NatRuleFields) error
	// plural names the rules in messages, e.g. "source NAT rules"
	plural string
	// exportNote is added to the help of export
	exportNote string
	// listHint is called after print, e.g. to tell that the outbound NAT mode ignores the manual rules
	listHint func(c *Context, api *firewall.FirewallApi, rules []firewall.NatRule)
}

func (kind *firewallNatKind) applyHint() string {
	return fmt.Sprintf(`Changes are only saved, run "/%s apply" to apply them.`, kind.path)
}

// firewallNatRegister adds the item commands of kind to its menu
func firewallNatRegister(kind *firewallNatKind) *Menu {
	var menu = Root.Menu(kind.path)
	menu.Help = kind.help
	var item = Arg{Name: "item", Help: firewallNatItemHelp, Positional: true, Required: true, Complete: kind.completeItems}
	menu.Add(
		&Command{Name: "print", Help: "list the rules in the order they are evaluated", Args: []Arg{
			{Name: "detail", Help: "show all fields of every rule", Type: Bool},
			{Name: "json", Help: "one JSON object per line, as the API returns them", Type: Bool},
			{Name: "search", Help: "only rules where any field contains this text"},
		}, Run: kind.print},
		&Command{Name: "show", Help: "show all fields of one rule", Args: []Arg{item}, Run: kind.show},
		&Command{Name: "add", Help: "add a rule, prints its uuid",
			Long: `The description names the rule: if a rule with this description exists already, add fails unless replace
is given, then that rule is replaced completely (fields not given are reset to their defaults, the position is
kept). New rules are added at the end, place-before puts them before another rule.
` + kind.long + kind.applyHint(),
			Args: append(kind.fieldArgs(true),
				Arg{Name: "place-before", Help: "add the rule before this rule (#, uuid or description)", Complete: kind.completeItems},
				Arg{Name: "replace", Help: "replace the rule with the same description", Type: Bool}),
			Run: kind.add},
		&Command{Name: "set", Help: "change fields of a rule, the others are kept",
			Long:  "An empty value clears a field, e.g. description=.\n" + kind.long + kind.applyHint(),
			Args:  append([]Arg{item}, kind.fieldArgs(false)...),
			Check: kind.checkSet, Run: kind.set},
		&Command{Name: "remove", Help: "remove a rule", Long: kind.applyHint(), Args: []Arg{item}, Run: kind.remove},
		&Command{Name: "enable", Help: "enable a rule", Long: kind.applyHint(), Args: []Arg{item}, Run: kind.enabler(true)},
		&Command{Name: "disable", Help: "disable a rule", Long: kind.applyHint(), Args: []Arg{item}, Run: kind.enabler(false)},
		&Command{Name: "move", Help: "move a rule before another rule, or to the end",
			Long: "Rules are evaluated in the order of print. " + kind.applyHint(),
			Args: []Arg{item, {Name: "destination", Help: "move the rule before this rule (#, uuid or description), to the end when not given",
				Complete: kind.completeItems}},
			Run: kind.move},
		&Command{Name: "export", Help: "save the rules as CSV, the format of the GUI export",
			Long: `Writes the rules (all fields, "@uuid" first, ; separated) to file=, - for stdout. An existing file is only
replaced with overwrite. Without rules nothing is written. The rules generated by OPNsense are not exported.` + kind.exportNote,
			Args: []Arg{
				{Name: "file", Positional: true, Required: true, Help: "the CSV file to write, - for stdout"},
				{Name: "overwrite", Type: Bool, Help: "replace an existing file"},
			},
			Check: firewallRuleTransferCheckOutput,
			Run:   kind.export},
		&Command{Name: "import", Help: "add and update rules from a CSV file (like the GUI import)",
			Long: firewallNatImportHelp + "\n" + kind.applyHint(),
			Args: []Arg{
				{Name: "file", Positional: true, Required: true, Help: "the CSV file to import"},
			},
			Confirm: "This adds " + kind.plural + " and overwrites the rules whose @uuid is in the file (no rule is removed).",
			Check:   firewallRuleImportCheck,
			Run:     kind.importRules},
		&Command{Name: "apply", Help: "reload the firewall rules and NAT, activating all saved firewall changes",
			Long: `Runs "filter reload": the saved changes of all firewall rules and NAT types become active at once. OPNsense
has no rollback for NAT changes.`,
			Confirm: "This loads the saved firewall rules and NAT into the firewall, a wrong rule can cut off access to it.",
			Run:     kind.apply},
	)
	return menu
}

const firewallNatImportHelp = `The file is a CSV like export writes (separated by ; or , with a header row). The import adds and
updates, it never removes: a row whose @uuid is an existing rule overwrites that rule's fields given in the file,
every other row (empty or unknown @uuid) adds a rule. The order columns sort_order and prio_group are ignored, the
position comes from the sequence column. The file is checked before anything is sent (CSV syntax, the same number
of columns in every row, @uuid format, known column names).
When OPNsense rejects rows it tries again without them and saves the others if they are valid on their own, so
check the rules after an error.`

// fieldArgs are the field arguments of add (with the required ones) and set
func (kind *firewallNatKind) fieldArgs(add bool) []Arg {
	var args = make([]Arg, 0, len(kind.fields)+2)
	for _, field := range kind.fields {
		var arg = field.arg
		arg.Required = add && field.required
		args = append(args, arg)
	}
	var disabled = Arg{Name: "disabled", Help: "keep the rule, but don't use it", Type: Bool}
	if add {
		disabled.Default = "no"
	}
	return append(args,
		Arg{Name: "description", Help: "description, also the name of the rule (at most 255 characters)", Validate: firewallNatValidateDescription},
		disabled)
}

// --- validation

func firewallNatValidateDescription(value string) error {
	if len([]rune(value)) > 255 {
		return errors.New("must be at most 255 characters")
	}
	for _, char := range value {
		if unicode.IsControl(char) {
			return fmt.Errorf("must not contain control characters like newlines, got %q", value)
		}
	}
	return nil
}

// firewallNatNamePattern matches alias names and the special networks (any, lan, wanip, (self))
var firewallNatNamePattern = regexp.MustCompile(`^(\(self\)|[A-Za-z_][A-Za-z0-9_.-]*)$`)

// firewallNatValidateAddress accepts an IP address, a network (CIDR) or the name of an alias or network
// (any, lan, wanip, (self)); empty clears the field
func firewallNatValidateAddress(value string) error {
	if value == "" || firewallNatNamePattern.MatchString(value) {
		return nil
	}
	if _, err := netip.ParseAddr(value); err == nil {
		return nil
	}
	if _, err := netip.ParsePrefix(value); err == nil {
		return nil
	}
	return fmt.Errorf("must be an IP address, a network like 198.51.100.0/24 or an alias name, got %q", value)
}

// firewallNatValidateIP accepts an IP address or a network (CIDR), no aliases
func firewallNatValidateIP(value string) error {
	if value == "" {
		return nil
	}
	if _, err := netip.ParseAddr(value); err == nil {
		return nil
	}
	if _, err := netip.ParsePrefix(value); err == nil {
		return nil
	}
	return fmt.Errorf("must be an IP address or a network like 198.51.100.0/24, got %q", value)
}

// firewallNatPortNamePattern matches well-known service names (http) and port alias names
var firewallNatPortNamePattern = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_.-]*$`)

// firewallNatValidatePort accepts a port, a range (80-90 or 80:90), a well-known service name or a port alias
func firewallNatValidatePort(value string) error {
	if value == "" || firewallNatPortNamePattern.MatchString(value) {
		return nil
	}
	var parts = strings.FieldsFunc(value, func(r rune) bool { return r == '-' || r == ':' })
	var valid = len(parts) == 1 && parts[0] == value || len(parts) == 2 && len(parts[0])+len(parts[1])+1 == len(value)
	for _, part := range parts {
		if number, err := strconv.Atoi(part); err != nil || number < 1 || number > 65535 {
			valid = false
		}
	}
	if !valid {
		return fmt.Errorf("must be a port 1-65535, a range like 8000-8080, a service name or a port alias, got %q", value)
	}
	return nil
}

// firewallNatFamily returns "inet" / "inet6" for an IP address or network, "" for names (aliases, any, lan)
func firewallNatFamily(value string) string {
	var addr, err = netip.ParseAddr(value)
	if err != nil {
		var prefix, prefixErr = netip.ParsePrefix(value)
		if prefixErr != nil {
			return ""
		}
		addr = prefix.Addr()
	}
	if addr.Is4() {
		return "inet"
	}
	return "inet6"
}

// firewallNatCheckFamily checks that the addresses in fields (by API field, argument name) match the IP
// protocol ("inet" / "inet6", anything else is not checked)
func firewallNatCheckFamily(fields firewall.NatRuleFields, protocol string, addresses [][2]string) error {
	if protocol != "inet" && protocol != "inet6" {
		return nil
	}
	for _, address := range addresses {
		if family := firewallNatFamily(fields[address[0]]); family != "" && family != protocol {
			return fmt.Errorf("%s %s does not match ip-protocol=%s", address[1], fields[address[0]], protocol)
		}
	}
	return nil
}

// firewallNatCheckPorts rejects ports (by API field, argument name) for protocols other than TCP and UDP
func firewallNatCheckPorts(fields firewall.NatRuleFields, protocol string, ports [][2]string) error {
	switch strings.ToLower(protocol) {
	case "tcp", "udp", "tcp/udp":
		return nil
	}
	for _, port := range ports {
		if fields[port[0]] != "" {
			var name = protocol
			if name == "" {
				name = "any"
			}
			return fmt.Errorf("%s is only valid with protocol=tcp, udp or tcp/udp, not %s", port[1], strings.ToLower(name))
		}
	}
	return nil
}

func (kind *firewallNatKind) checkSet(args *Args) error {
	for _, name := range args.Given() {
		if name != "item" {
			return nil
		}
	}
	return errors.New("nothing to change, give at least one field like description= (type \"set ?\" for help)")
}

// --- conversion

func (field firewallNatField) toAPI(kind *firewallNatKind, args *Args) string {
	var name = field.arg.Name
	switch field.conv {
	case firewallNatFlag:
		return Flag(args.Bool(name))
	case firewallNatList:
		return strings.Join(args.List(name), ",")
	case firewallNatMapped:
		var value = strings.TrimSpace(args.String(name))
		for _, pair := range field.values {
			if strings.EqualFold(pair[0], value) {
				return pair[1]
			}
		}
		return value
	case firewallNatProtocol:
		return kind.protocol(strings.TrimSpace(args.String(name)))
	default:
		return strings.TrimSpace(args.String(name))
	}
}

// display renders an API value like the argument takes it
func (field firewallNatField) display(value string) string {
	switch field.conv {
	case firewallNatFlag:
		return YesNo(value)
	case firewallNatMapped:
		for _, pair := range field.values {
			if pair[1] == value {
				return pair[0]
			}
		}
		return value
	case firewallNatProtocol:
		if value == "" {
			return "any"
		}
		return strings.ToLower(value)
	default:
		return value
	}
}

// apiFields returns the given field arguments as API fields; with all also the defaults of the fields not given
// (except keep fields), the description and the on/off state
func (kind *firewallNatKind) apiFields(rules *firewall.NatRules, args *Args, all bool) firewall.NatRuleFields {
	var fields = firewall.NatRuleFields{}
	for _, field := range kind.fields {
		switch {
		case args.Has(field.arg.Name):
			fields[field.api] = field.toAPI(kind, args)
		case all && !field.keep:
			fields[field.api] = field.def
		}
	}
	if all || args.Has("description") {
		fields[rules.DescriptionField()] = strings.TrimSpace(args.String("description"))
	}
	if all || args.Has("disabled") {
		fields[rules.DisabledField()] = rules.DisabledValue(args.Bool("disabled"))
	}
	return fields
}

// merged returns the fields of rule with the changes
func firewallNatMerged(base firewall.NatRuleFields, changes firewall.NatRuleFields) firewall.NatRuleFields {
	var merged = firewall.NatRuleFields{}
	for name, value := range base {
		merged[name] = value
	}
	for name, value := range changes {
		merged[name] = value
	}
	return merged
}

// defaults are the API fields of a new rule
func (kind *firewallNatKind) defaults() firewall.NatRuleFields {
	var fields = firewall.NatRuleFields{}
	for _, field := range kind.fields {
		fields[field.api] = field.def
	}
	return fields
}

// checkOptions validates the given option fields (interface, protocol, ...) against the options of get_rule
func (kind *firewallNatKind) checkOptions(rules *firewall.NatRules, changes firewall.NatRuleFields) error {
	var options map[string][]string
	for _, field := range kind.fields {
		var value, given = changes[field.api]
		if !given || value == "" || field.conv == firewallNatMapped || field.conv == firewallNatFlag {
			continue
		}
		if options == nil {
			var err error
			if options, err = rules.Options(); err != nil {
				return err
			}
		}
		var available, isOption = options[field.api]
		if !isOption {
			continue
		}
		for _, element := range strings.Split(value, ",") {
			var known = false
			for _, option := range available {
				known = known || option == element
			}
			if !known {
				var names = make([]string, 0, len(available))
				for _, option := range available {
					if option != "" {
						names = append(names, field.display(option))
					}
				}
				return fmt.Errorf("unknown %s %q, the choices are: %s", field.arg.Name, field.display(element), strings.Join(names, ", "))
			}
		}
	}
	return nil
}

// --- lookups

func (kind *firewallNatKind) api(c *Context) (*firewall.FirewallApi, *firewall.NatRules, error) {
	var api, err = firewallApi(c)
	if err != nil {
		return nil, nil, err
	}
	return api, kind.rules(api), nil
}

// selectRule loads all rules and finds the one selector refers to, it also returns all rules
func (kind *firewallNatKind) selectRule(c *Context, rules *firewall.NatRules, selector string) (firewall.NatRule, []firewall.NatRule, error) {
	var list, err = rules.List()
	if err != nil {
		return firewall.NatRule{}, nil, err
	}
	var rule, selectErr = Select(c, selector, list,
		func(rule firewall.NatRule) string { return rule.Uuid },
		func(rule firewall.NatRule) []string { return []string{rules.Description(rule)} })
	return rule, list, selectErr
}

// selectChangeable is selectRule refusing the rules generated by OPNsense
func (kind *firewallNatKind) selectChangeable(c *Context, rules *firewall.NatRules, selector string) (firewall.NatRule, []firewall.NatRule, error) {
	var rule, list, err = kind.selectRule(c, rules, selector)
	if err == nil && rule.Automatic {
		err = fmt.Errorf("the %s %s (%s) is generated by OPNsense and can not be changed", rules.Name(), rule.Uuid, rules.Description(rule))
	}
	return rule, list, err
}

func (kind *firewallNatKind) completeItems(c *Context) []string {
	var _, rules, err = kind.api(c)
	if err != nil {
		return nil
	}
	var list, listErr = rules.List()
	if listErr != nil {
		return nil
	}
	var names []string
	for _, rule := range list {
		if description := rules.Description(rule); description != "" && !rule.Automatic {
			names = append(names, description)
		}
	}
	return names
}

// completeOption returns a completion of the get_rule options of an API field
func (kind *firewallNatKind) completeOption(apiField string) func(c *Context) []string {
	return func(c *Context) []string {
		var _, rules, err = kind.api(c)
		if err != nil {
			return nil
		}
		var options, optionsErr = rules.Options()
		if optionsErr != nil {
			return nil
		}
		var names []string
		for _, option := range options[apiField] {
			if option != "" {
				names = append(names, strings.ToLower(option))
			}
		}
		return names
	}
}

// sameDescription returns the configured rules (other than except) with the description
func firewallNatSameDescription(rules *firewall.NatRules, list []firewall.NatRule, description string, except string) []firewall.NatRule {
	var matching []firewall.NatRule
	for _, rule := range list {
		if !rule.Automatic && rule.Uuid != except && strings.EqualFold(rules.Description(rule), description) {
			matching = append(matching, rule)
		}
	}
	return matching
}

func firewallNatUuids(list []firewall.NatRule) string {
	var uuids = make([]string, len(list))
	for i, rule := range list {
		uuids[i] = rule.Uuid
	}
	return strings.Join(uuids, ", ")
}

// --- output

// firewallNatEndpoint renders a source or destination: "!" for inverted, the network and the port
func firewallNatEndpoint(network string, invert string, port string) string {
	if network == "" {
		network = "any"
	}
	if invert == "1" {
		network = "!" + network
	}
	if port != "" {
		network += " port " + port
	}
	return network
}

func (kind *firewallNatKind) details(rules *firewall.NatRules, rule firewall.NatRule) [][2]string {
	var fields = [][2]string{
		{"uuid", rule.Uuid},
		{"disabled", YesNo(Flag(rules.Disabled(rule)))},
		{"automatic", YesNo(Flag(rule.Automatic))},
	}
	if rule.Inactive {
		fields = append(fields, [2]string{"inactive", "yes (ignored by the outbound NAT mode)"})
	}
	for _, field := range kind.fields {
		var value = field.display(rule.Fields[field.api])
		if description := rule.Fields["%"+field.api]; description != "" && (field.conv == firewallNatText || field.conv == firewallNatList) && description != value {
			value = fmt.Sprintf("%s (%s)", value, description)
		}
		fields = append(fields, [2]string{field.arg.Name, value})
	}
	return append(fields, [2]string{"description", rules.Description(rule)})
}

func firewallNatMatches(rule firewall.NatRule, phrase string) bool {
	phrase = strings.ToLower(phrase)
	for _, value := range rule.Fields {
		if strings.Contains(strings.ToLower(value), phrase) {
			return true
		}
	}
	return false
}

func (kind *firewallNatKind) print(c *Context, args *Args) error {
	var api, rules, err = kind.api(c)
	if err != nil {
		return err
	}
	var all, listErr = rules.List()
	if listErr != nil {
		return listErr
	}
	var list []firewall.NatRule
	for _, rule := range all {
		if !args.Has("search") || firewallNatMatches(rule, args.String("search")) {
			list = append(list, rule)
		}
	}

	var uuids = make([]string, len(list))
	for i, rule := range list {
		uuids[i] = rule.Uuid
	}
	switch {
	case args.Bool("json"):
		for _, rule := range list {
			var compact, compactErr = firewallNatCompact(rule.Raw)
			if compactErr != nil {
				return compactErr
			}
			c.Println(compact)
		}
	case args.Bool("detail"):
		var items = make([][][2]string, len(list))
		for i, rule := range list {
			items[i] = kind.details(rules, rule)
		}
		c.Details(items, uuids)
	default:
		var rows = make([][]string, len(list))
		for i, rule := range list {
			var auto = ""
			if rule.Automatic {
				auto = "yes"
			}
			var row = append([]string{YesNo(Flag(rules.Disabled(rule))), auto}, kind.row(rule.Fields)...)
			rows[i] = append(row, rules.Description(rule))
		}
		var headers = append(append([]string{"DISABLED", "AUTO"}, kind.columns...), "DESCRIPTION")
		c.Items(headers, rows, uuids)
	}
	if kind.listHint != nil {
		kind.listHint(c, api, list)
	}
	return nil
}

// firewallNatCompact returns the API row as one line
func firewallNatCompact(raw json.RawMessage) (string, error) {
	var buffer bytes.Buffer
	if err := json.Compact(&buffer, raw); err != nil {
		return "", err
	}
	return buffer.String(), nil
}

func (kind *firewallNatKind) show(c *Context, args *Args) error {
	var _, rules, err = kind.api(c)
	if err != nil {
		return err
	}
	var rule, _, selectErr = kind.selectRule(c, rules, args.String("item"))
	if selectErr != nil {
		return selectErr
	}
	c.Fields(kind.details(rules, rule))
	return nil
}

// --- changes

func (kind *firewallNatKind) add(c *Context, args *Args) error {
	var _, rules, err = kind.api(c)
	if err != nil {
		return err
	}
	var replace = args.Bool("replace")
	var fields = kind.apiFields(rules, args, replace)
	if !replace { // the disabled default is always sent, OPNsense would enable the rule
		fields[rules.DisabledField()] = rules.DisabledValue(args.Bool("disabled"))
	}
	if err := kind.check(firewallNatMerged(kind.defaults(), fields)); err != nil {
		return err
	}
	if err := kind.checkOptions(rules, fields); err != nil {
		return err
	}

	var list, listErr = rules.List()
	if listErr != nil {
		return listErr
	}
	var before firewall.NatRule
	if args.Has("place-before") {
		var selectErr error
		if before, _, selectErr = kind.selectChangeable(c, rules, args.String("place-before")); selectErr != nil {
			return fmt.Errorf("place-before: %w", selectErr)
		}
	}

	var description = fields[rules.DescriptionField()]
	var existing []firewall.NatRule
	if description != "" {
		existing = firewallNatSameDescription(rules, list, description, "")
	}
	var uuid string
	switch {
	case len(existing) == 0:
		if uuid, err = rules.Create(fields); err != nil {
			return err
		}
	case len(existing) > 1:
		return &coreapi.TooManyFoundError{Name: fmt.Sprintf("there are %d rules with description %q (%s), change or remove them with set or remove",
			len(existing), description, firewallNatUuids(existing))}
	case !replace:
		return fmt.Errorf("a rule with description %q exists already (%s), change it with set or replace it with add ... replace",
			description, existing[0].Uuid)
	default:
		uuid = existing[0].Uuid
		if err := rules.Update(uuid, fields); err != nil {
			return err
		}
		c.Infof("replaced the existing rule %q", description)
	}
	c.Println(uuid)

	if before.Uuid != "" && before.Uuid != uuid {
		if err := rules.MoveBefore(uuid, before.Uuid); err != nil {
			return fmt.Errorf("the rule %s was saved, but moving it before %s failed: %w", uuid, before.Uuid, err)
		}
	}
	return nil
}

func (kind *firewallNatKind) set(c *Context, args *Args) error {
	var _, rules, err = kind.api(c)
	if err != nil {
		return err
	}
	var rule, list, selectErr = kind.selectChangeable(c, rules, args.String("item"))
	if selectErr != nil {
		return selectErr
	}
	var changes = kind.apiFields(rules, args, false)
	if err := kind.check(firewallNatMerged(rule.Fields, changes)); err != nil {
		return err
	}
	if err := kind.checkOptions(rules, changes); err != nil {
		return err
	}
	if description := changes[rules.DescriptionField()]; description != "" {
		if others := firewallNatSameDescription(rules, list, description, rule.Uuid); len(others) > 0 {
			return fmt.Errorf("another rule with description %q exists already (%s)", description, firewallNatUuids(others))
		}
	}
	return rules.Update(rule.Uuid, changes)
}

func (kind *firewallNatKind) remove(c *Context, args *Args) error {
	var _, rules, err = kind.api(c)
	if err != nil {
		return err
	}
	var rule, _, selectErr = kind.selectChangeable(c, rules, args.String("item"))
	if selectErr != nil {
		return selectErr
	}
	return rules.Remove(rule.Uuid)
}

func (kind *firewallNatKind) enabler(enabled bool) func(c *Context, args *Args) error {
	return func(c *Context, args *Args) error {
		var _, rules, err = kind.api(c)
		if err != nil {
			return err
		}
		var rule, _, selectErr = kind.selectChangeable(c, rules, args.String("item"))
		if selectErr != nil {
			return selectErr
		}
		var changed, toggleErr = rules.SetEnabled(rule.Uuid, enabled)
		if toggleErr != nil {
			return toggleErr
		}
		if !changed {
			c.Infof("the rule %s is already %s", rule.Uuid, EnabledWord(enabled))
		}
		return nil
	}
}

func (kind *firewallNatKind) move(c *Context, args *Args) error {
	var _, rules, err = kind.api(c)
	if err != nil {
		return err
	}
	var rule, _, selectErr = kind.selectChangeable(c, rules, args.String("item"))
	if selectErr != nil {
		return selectErr
	}
	if !args.Has("destination") || args.String("destination") == "" {
		return rules.MoveToEnd(rule.Uuid)
	}
	var destination, _, destinationErr = kind.selectChangeable(c, rules, args.String("destination"))
	if destinationErr != nil {
		return fmt.Errorf("destination: %w", destinationErr)
	}
	return rules.MoveBefore(rule.Uuid, destination.Uuid)
}

func (kind *firewallNatKind) apply(c *Context, _ *Args) error {
	var _, rules, err = kind.api(c)
	if err != nil {
		return err
	}
	return rules.Apply()
}

// --- export / import (the file handling is shared with /firewall/rule, see firewall_rule_transfer.go)

func (kind *firewallNatKind) export(c *Context, args *Args) error {
	var _, rules, err = kind.api(c)
	if err != nil {
		return err
	}
	var content, exportErr = rules.Export()
	if exportErr != nil {
		return exportErr
	}
	return firewallRuleTransferSave(c, content, args.String("file"), args.Bool("overwrite"), kind.plural)
}

func (kind *firewallNatKind) importRules(c *Context, args *Args) error {
	var file = args.String("file")
	var content, parsed, err = firewallRuleImportRead(file)
	if err != nil {
		return err
	}
	_, rules, err := kind.api(c)
	if err != nil {
		return err
	}

	// OPNsense silently ignores unknown columns, a misspelled column would quietly import nothing for it
	columns, err := rules.Columns()
	if err != nil {
		return err
	}
	var unknown []string
	for _, name := range parsed.Header {
		if !slices.Contains(columns, name) {
			unknown = append(unknown, name)
		}
	}
	if len(unknown) > 0 {
		return fmt.Errorf("%s: unknown columns %s, valid are: %s", file, strings.Join(unknown, ", "), strings.Join(columns, ", "))
	}

	result, err := rules.Import(content, filepath.Base(file))
	if err != nil {
		return err
	}
	if len(result.Validations) == 0 {
		c.Infof("imported %s: %d rules added, %d updated", file, result.Inserted, result.Updated)
		return nil
	}
	var lines []string
	for _, validation := range result.Validations {
		var where = "file"
		if validation.Row >= 0 {
			where = fmt.Sprintf("line %d", validation.Row+2)
		}
		var field = ""
		if validation.Field != "" {
			field = validation.Field + ": "
		}
		lines = append(lines, fmt.Sprintf("  %s: %s%s", where, field, validation.Message))
	}
	return fmt.Errorf("OPNsense rejected rows of %s:\n%s\nthe other rows were saved if they are valid without the rejected ones, check the rules",
		file, strings.Join(lines, "\n"))
}
